import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"56、【旅】 艮下离上","description":"周易口诀义 - 56、【旅】 艮下离上","frontmatter":{"title":"56、【旅】 艮下离上","description":"周易口诀义 - 56、【旅】 艮下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/058.md","filePath":"zh/classics/koujueyi/058.md"}'),r={name:"zh/classics/koujueyi/058.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_56、【旅】-艮下离上" tabindex="-1">56、【旅】 艮下离上 <a class="header-anchor" href="#_56、【旅】-艮下离上" aria-label="Permalink to “56、【旅】 艮下离上”">​</a></h1><p>彖曰：「旅小亨」，柔得中乎外而顺乎刚，止而丽乎明，是以「小亨，旅贞吉」也。旅之时义大矣哉！</p><p>象曰：山上有火，旅。君子以明慎用刑而不留狱。</p><p>初六：旅琐琐，斯其所取灾。</p><p>象曰：「旅琐琐」，志穷灾也。</p><p>六二：旅即次，怀其资，得童仆贞。</p><p>象曰：「得童仆贞」，终无尤也。</p><p>九三：旅焚其次，丧其童仆，贞厉。</p><p>象曰：「旅焚其次」，亦以伤矣。以旅与下，其义丧也。</p><p>九四：旅于处，得其资斧，我心不快。</p><p>象曰：「旅于处」，未得位也；「得其资斧」，心未快也。</p><p>六五，射雉，一矢亡，终以誉命。</p><p>象曰：「终以誉命」，上逮也。</p><p>上九，鸟焚其巢，旅人先笑后号啕，丧牛于易，凶。</p><p>象曰：以旅在上，其义焚也，「丧牛于易」，终莫之闻也。</p><p>解读</p><p>「旅小亨，旅贞吉」者，旅者，客羁旅之称也。旅人触目乖阻，困于途路，求容仅存，假道济通，所通非大，但「小亨」而已，故「旅小亨」也。羁旅而得小通，是旅之正吉，故「旅贞吉」也。象曰「山上有火，旅」者，火在山上，因风而起，逐草而行，势不久留之象也。「君子以明慎用刑而不留狱」者，旅卦而引断狱。案六十四卦有文明者多称用刑，今旅卦有艮止离明，止即审慎用刑，明即不滥不枉，故圣人之意，取其明察止审，不妄刑罚。盖以人命至重，故阳肤为士师，曾子诫之曰「治狱之道，如得其情，则哀矜而勿喜，死者不可复生，断者不可复续」是也。</p><p>「初六曰：旅琐琐，斯其所取灾」者，琐琐，细小卑贱之貌也。处旅之时，最居人下，是卑贱细小矣，故「旅琐琐」也。身处人下，不得所安，有所兴为，灾祸自至，故曰「斯其所取灾」。</p><p>「六二，旅即次，怀其资，得童仆贞」者，次是旅店，旅人所居之处也。六二以柔居中，得位乘上，即是旅人得其所安，只可店舍而处，故曰「旅即次」也。处旅行谦，不为刚猛，但有童仆之正，怀来资货，不虑丧失，故曰「怀其资，得童仆贞」也。</p><p>「九三，旅焚其次，丧其童仆，贞厉」者，九三处下卦之上，上无应，与初二相得，遂欲自尊而施惠于下。当旅之时，不能谦和静慎，而乃预萌侵权，为君所疑，遂被黜夺，焚其次舍，是丧童仆之正而身危矣，故曰「丧其童仆，贞厉」。</p><p>「九四，旅于处，得其资斧，我心不快」者，九四以阳居阴，即怀谦之道。处旅行谦，虽不得平坦之处，而得用斧之地，谓除荆棘而治次舍，以自居之，故曰「旅于处，得其资斧」也。寄旅求安，不得平坦而得荆棘之地，即其心不乐，故曰「我心不快」也。</p><p>「六五：射雉，一矢亡，终以誉命」者，羁旅之时，不可以处盛位，纵使居之，终不可保有，喻射雉一矢，射之不中而失其矢，雉虽有而终不可得，故曰「射雉一矢亡」也。然五居文明之中，能审祸福之机，不乘刚而专权，但弃下而恭愿奉上，故终美誉而见命也。</p><p>上九：鸟焚其巢，旅人先笑而后号啕。「丧牛于易，凶」者，居高危以为宅，鸟巢之象。旅人最处高位，众心所嫉，居嫉害之地，因被侵夺，必致凶塞。得高位而先笑也，凶祸至而后号啕也。侵夺而似鸟焚巢，牛是稼穑之资，丧失其牛，理在不难，众所同嫉，物莫之与，危而弗扶，无人以为闻报，无所依托，即伤切甚矣，故于易凶。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
